SINA_SMART["physio1-cardiovascular"] = {"lecture":"physio1-cardiovascular","title":"The cardiovascular system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-cardiovascular:e0","text":"Heart, vessels and blood; two loops in series (pulmonary, systemic).","topic":"Components and circuits","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e1","text":"Systemic circulation holds ~84% of blood volume.","topic":"Components and circuits","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e2","text":"Arteries leave the heart, veins return to it; pulmonary arteries carry O₂-poor blood.","topic":"Components and circuits","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e3","text":"Poiseuille: R = 8ηL / πr⁴ (viscosity, length, radius⁴).","topic":"Pressure, flow and resistance","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e4","text":"Radius is the main moment-to-moment control; arterioles = resistance vessels.","topic":"Pressure, flow and resistance","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e5","text":"Aorta ~120/80 mmHg; pulmonary artery ~20/8 mmHg.","topic":"Pressure, flow and resistance","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e6","text":"Velocity lowest in capillaries (largest total area).","topic":"Pressure, flow and resistance","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e7","text":"Endothelium releases EDRF = NO → smooth muscle relaxation.","topic":"The endothelium and nitric oxide","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiovascular:e8","text":"ACh relaxes vessels only with intact endothelium (Furchgott); Nobel 1998.","topic":"The endothelium and nitric oxide","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"16i7ybg":"a","yb52c":"a","1qgata8":"a","1maiz01":"a","1pdsjsg":"a","1qvsebh":"a","frab2s":"a","eodvp7":"a","1kweej6":"a","1p36tt9":"a","1x05lpu":"a","7amop":"a","1e5yepg":"a","wro4uo":"a","bjucql":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-cardiovascular:e0":{"s":0,"u":["Heart, vessels and blood; two loops in series (pulmonary, systemic).","Two loops run in series in a closed system: the pulmonary loop takes oxygen-poor blood to the lungs and back, and the systemic loop takes blood from the heart to the rest of the body.","The cardiovascular system has three components: the heart (pump), the blood vessels (pipes) and the blood (the fluid)."],"dp":[]},"physio1-cardiovascular:e1":{"s":0,"u":["Systemic circulation holds ~84% of blood volume.","The systemic circulation holds about 84% of the blood volume ."],"dp":[]},"physio1-cardiovascular:e2":{"s":0,"u":["Arteries leave the heart, veins return to it; pulmonary arteries carry O₂-poor blood.","All arteries carry blood away from the heart, all veins towards it .","Usually arteries carry oxygenated blood, except the pulmonary arteries (deoxygenated to the lungs) and the pulmonary veins (four, oxygenated to the left atrium)."],"dp":[]},"physio1-cardiovascular:e3":{"s":1,"u":["Poiseuille: R = 8ηL / πr⁴ (viscosity, length, radius⁴).","By Poiseuille's law , R = 8ηL / πr⁴ : resistance depends on (1) blood viscosity (η, mainly red cell count), (2) vessel length and (3) vessel radius , to the fourth power.","Radius is the main minute-to-minute control: halving the radius multiplies resistance by 16."],"dp":[]},"physio1-cardiovascular:e4":{"s":1,"u":["Radius is the main moment-to-moment control; arterioles = resistance vessels.","Arterioles , small and muscular, are the main resistance vessels.","Radius is the main minute-to-minute control: halving the radius multiplies resistance by 16."],"dp":[]},"physio1-cardiovascular:e5":{"s":1,"u":["Aorta ~120/80 mmHg; pulmonary artery ~20/8 mmHg.","Typical pressures: aorta about 120/80 mmHg , falling along arterioles and capillaries (about 35 at the arterial end) to near 0-7 mmHg in the right atrium; pulmonary artery about 20/8 mmHg ."],"dp":[]},"physio1-cardiovascular:e6":{"s":1,"u":["Velocity lowest in capillaries (largest total area).","Velocity is flow divided by cross-sectional area (Q = v × S), so blood is slowest in the capillaries, whose total area is largest."],"dp":[]},"physio1-cardiovascular:e7":{"s":2,"u":["Endothelium releases EDRF = NO → smooth muscle relaxation.","The endothelium releases an endothelium-derived relaxing factor (EDRF) , identified as nitric oxide (NO) .","Stimuli such as shear stress , acetylcholine, ADP and serotonin raise endothelial Ca²⁺, activating NO synthase ; NO diffuses to smooth muscle and causes relaxation , acting as a brake on vasoconstriction."],"dp":[{"h":"Nitroglycerin: an old drug explained by NO","t":"Nitroglycerin relieved angina in the 1870s, long before anyone knew why. It is an NO donor : it releases nitric oxide in vascular smooth muscle, mimicking the endothelium's own relaxing factor. Veins dilate most, lowering the return of blood to the heart and so the heart's work and oxygen demand; coronary arteries dilate too. The same pathway explains sildenafil's interaction with nitrates: both raise the same messenger (cGMP), and together they can drop blood pressure dangerously. Source: the lecture's EDRF/NO slides (NO donors)."}]},"physio1-cardiovascular:e8":{"s":2,"u":["ACh relaxes vessels only with intact endothelium (Furchgott); Nobel 1998.","Furchgott showed that acetylcholine relaxes a rabbit aorta only if its endothelium is intact : without endothelium it constricts.","Furchgott, Ignarro and Murad received the 1998 Nobel Prize for this discovery."],"dp":[]}},"meta":{"16i7ybg":{"a":"recall","vg":"physio1-cardiovascular:e2/recall/1"},"yb52c":{"a":"recall","vg":"physio1-cardiovascular:e2/recall/2"},"1qgata8":{"a":"recall","vg":"physio1-cardiovascular:e1/recall/1"},"1maiz01":{"a":"recall","vg":"physio1-cardiovascular:e3/recall/1"},"1pdsjsg":{"a":"application","vg":"physio1-cardiovascular:e4/application/1"},"1qvsebh":{"a":"recall","vg":"physio1-cardiovascular:e4/recall/1"},"frab2s":{"a":"recall","vg":"physio1-cardiovascular:e3/recall/2"},"eodvp7":{"a":"recall","vg":"physio1-cardiovascular:e6/recall/1"},"1kweej6":{"a":"recall","vg":"physio1-cardiovascular:e5/recall/1"},"1p36tt9":{"a":"recall","vg":"physio1-cardiovascular:e5/recall/1"},"1x05lpu":{"a":"recall","vg":"physio1-cardiovascular:e7/recall/1"},"7amop":{"a":"recall","vg":"physio1-cardiovascular:e8/recall/1"},"1e5yepg":{"a":"recall","vg":"physio1-cardiovascular:e7/recall/2"},"wro4uo":{"a":"recall","vg":"physio1-cardiovascular:e7/recall/3"}},"explRev":"98fb03015ac1"};
